{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Surveillance Data",
    "operation": "add",
    "url": "http://localhost:7807",
    "widgets_json": {
      "case_qa_omni": {
        "name": "Case Q&A",
        "description": "Ask questions over the surveillance case corpus.",
        "endpoint": "/case-qa",
        "type": "omni",
        "params": [
          {
            "paramName": "prompt",
            "type": "text",
            "label": "Prompt",
            "show": false,
            "description": "Question to run over the case corpus."
          }
        ],
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 900000
      },
      "alert_queue": {
        "name": "Alert Queue",
        "description": "Open surveillance alerts.",
        "endpoint": "/alert-queue",
        "type": "table",
        "params": [
          {
            "paramName": "severity",
            "type": "text",
            "label": "Severity",
            "options": [
              "High",
              "Medium",
              "Low"
            ],
            "default": "high"
          }
        ],
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 900000,
        "data": {
          "columnsDefs": [
            {
              "field": "alert_id",
              "headerName": "Alert",
              "cellDataType": "text"
            },
            {
              "field": "desk",
              "headerName": "Desk",
              "cellDataType": "text"
            },
            {
              "field": "severity",
              "headerName": "Severity",
              "cellDataType": "text",
              "renderFn": "titleCase"
            },
            {
              "field": "age_days",
              "headerName": "Age (d)",
              "cellDataType": "number",
              "formatterFn": "int"
            }
          ]
        }
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "gridData": {
          "w": 5,
          "h": 4
        },
        "staleTime": 900000
      }
    }
  }
}

